// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === 'string') ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // Normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Função auxiliar para sortear uma mensagem da lista
function pick(arr) {
  if (!arr || arr.length === 0) return "";
  return arr[Math.floor(Math.random() * arr.length)];
}

// 1. Busca os clientes (seja do Merge ou do nó Webhook)
let clientes = [];
try {
  clientes = $('Webhook').first().json.body?.clientes || $('Webhook').first().json.clientes || [];
} catch (e) {
  clientes = $json.body?.clientes || $json.clientes || [];
}

// 2. Busca os investimentos (do nó Code anterior ou do Merge)
let investimentos = [];
try {
  investimentos = $('Code').first().json.investimentos || [];
} catch (e) {
  investimentos = $json.investimentos || [];
}

// 3. Processa cada cliente e cruza com os investimentos compatíveis
const resultados = clientes.map(c => {
  const nome = c.nome || "Cliente";
  const email = c.email || "";
  const perfil = c.perfil || "Conservador";

  // Converte o saldo de texto para número (ex: "R$ 1.000,00" -> 1000)
  const saldoNum = Number(String(c.saldo).replace(/[^\d]/g, "")) || 0;

  // Filtra produtos do mesmo perfil e que o saldo cubra o valor mínimo
  const compativeis = investimentos.filter(inv => 
    String(inv.perfil).toLowerCase() === perfil.toLowerCase() && 
    (inv.minimo || 0) <= saldoNum
  );

  // Escolhe o produto compatível (ou o padrão do perfil caso o saldo seja menor)
  const escolhido = compativeis.length > 0 
    ? compativeis[compativeis.length - 1] 
    : (investimentos.find(inv => String(inv.perfil).toLowerCase() === perfil.toLowerCase()) || { produto: "Tesouro Selic", rentabilidade: "13.0%" });

  const motivo = `Recomendação compatível com perfil ${perfil} e valor mínimo de investimento.`;

  // Cria variações de mensagens personalizadas
  const mensagens = [
    `Olá, ${nome}! Com base no seu perfil ${perfil}, identificamos uma ótima oportunidade: ${escolhido.produto} com rentabilidade de ${escolhido.rentabilidade}.`,
    `Oi ${nome}, que tal colocar seu saldo de ${c.saldo} para render? Recomendamos o ${escolhido.produto} (${escolhido.rentabilidade}), ideal para você!`,
    `Prezado(a) ${nome}, preparamos uma recomendação exclusiva para o seu perfil ${perfil}: conheça o ${escolhido.produto}.`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// 4. Retorno estruturado idêntico ao do professor
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

// Função para converter dinheiro brasileiro ("R$ 12.500,00") para número puro (12500)
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente (desempacota para o n8n poder mandar e-mails um por um)
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: c.email,
      nome: c.nome,
      perfil: c.perfil,
      saldo_texto: c.saldo_texto || c.saldo || "",
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      produto: c.recomendacao?.produto || "",
      rentabilidade: c.recomendacao?.rentabilidade || "",
      motivo: c.motivo || "",
      mensagem: c.mensagem_escolhida || ""
    }
  };
});

return out;

