// Pega todos os itens da IA e todos os clientes originais
const itensDaIA = $input.all();
let clientesOriginais = [];

try {
  clientesOriginais = $('Code in JavaScript2').all();
} catch (e) {
  clientesOriginais = [];
}

return itensDaIA.map((item, index) => {
  // Resgata o cliente original correspondente
  const cliente = clientesOriginais[index]?.json || {};
  const destinatario = cliente.email_to || cliente.email || cliente.to || "";
  const nomeCliente = cliente.nome || "Cliente";

  // Extrai a resposta que a IA gerou
  let rawContent = item.json.text || item.json.response?.text || item.json.message?.content || item.json.content || "";
  if (typeof rawContent !== "string") {
    rawContent = JSON.stringify(rawContent);
  }

  // Limpa as crases de markdown (```json ... ```)
  const cleaned = rawContent
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  let parsed = {};
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    parsed = {
      subject: `Oportunidade de Investimento - ${nomeCliente}`,
      text_body: cleaned,
      html_body: `<p>${cleaned.replace(/\n/g, "<br>")}</p>`
    };
  }

  const subject = (parsed.subject || `Recomendação de Investimento - ${nomeCliente}`).trim();
  const text_body = (parsed.text_body || "").trim();
  let html_body = (parsed.html_body || `<p>${text_body}</p>`).trim();

  if (!html_body.startsWith("<") && !html_body.includes("<p>")) {
    html_body = `<p>${html_body.replace(/\n/g, "<br>")}</p>`;
  }

  return {
    json: {
      ok: true,
      to: destinatario,         // Nome que o professor usou
      email_to: destinatario,   // Mantemos também por segurança
      nome: nomeCliente,
      subject,
      text_body,
      html_body
    }
  };
});
